-- Fly
local flyOn = false
local gyro, vel
btn(tabs.Opcoes,"Fly ☠️",10).MouseButton1Click:Connect(function()
	flyOn = not flyOn
	local hrp = LocalPlayer.Character and LocalPlayer.Character:FindFirstChild("HumanoidRootPart")
	if flyOn and hrp then
		gyro = Instance.new("BodyGyro",hrp)
		vel = Instance.new("BodyVelocity",hrp)
		gyro.P = 9e4
		vel.MaxForce = Vector3.new(9e4,9e4,9e4)
	else
		if gyro then gyro:Destroy() end
		if vel then vel:Destroy() end
	end
end)

RunService.RenderStepped:Connect(function()
	if flyOn and vel and gyro then
		vel.Velocity = Camera.CFrame.LookVector * 50
		gyro.CFrame = Camera.CFrame
	end
end)

