-------------------- ANTIS 🛡️ --------------------

-- 1. Anti Fling
-- Explicação: Ele detecta se sua velocidade está alta demais (comum em ataques de fling) e reseta sua velocidade linear/angular.
local antiFlingOn = false
btn(tabs.Antis, "Anti Fling", 10).MouseButton1Click:Connect(function()
    antiFlingOn = not antiFlingOn
    print("Anti Fling: " .. tostring(antiFlingOn))
end)

RunService.Heartbeat:Connect(function()
    if antiFlingOn and LocalPlayer.Character then
        local hrp = LocalPlayer.Character:FindFirstChild("HumanoidRootPart")
        if hrp then
            hrp.RotVelocity = Vector3.new(0, 0, 0)
            hrp.Velocity = Vector3.new(hrp.Velocity.X, hrp.Velocity.Y, hrp.Velocity.Z)
        end
    end
end)

-- 2. Anti Cooldown (BETA)
-- Nota: Isso funciona em ferramentas que usam tempo de espera local. 
-- Em alguns jogos, o tempo é controlado pelo servidor e pode não funcionar 100%.
btn(tabs.Antis, "Anti Cooldown", 50).MouseButton1Click:Connect(function()
    for _, tool in pairs(LocalPlayer.Backpack:GetChildren()) do
        if tool:IsA("Tool") then
            -- Tenta forçar o tempo de espera para zero
            if tool:FindFirstChild("Cooldown") then tool.Cooldown.Value = 0 end
            -- Muitos scripts usam variáveis locais, tentamos resetar o estado da Tool
            tool.Enabled = true
        end
    end
end)

-- 3. Anti AFK
-- Impede que o Roblox te desconecte por inatividade.
btn(tabs.Antis, "Anti AFK", 90).MouseButton1Click:Connect(function()
    local vu = game:GetService("VirtualUser")
    LocalPlayer.Idled:Connect(function()
        vu:Button2Down(Vector2.new(0,0), workspace.CurrentCamera.CFrame)
        task.wait(1)
        vu:Button2Up(Vector2.new(0,0), workspace.CurrentCamera.CFrame)
    end)
    print("Anti AFK Ativado")
end)

-- 4. Anti Lag (Remover Texturas)
-- Deixa o jogo com visual "plastic" para ganhar FPS.
btn(tabs.Antis, "Anti Lag (FPS Boost)", 130).MouseButton1Click:Connect(function()
    local terrain = workspace:FindFirstChildOfClass('Terrain')
    terrain.WaterWaveSize = 0
    terrain.WaterWaveSpeed = 0
    terrain.WaterReflectance = 0
    terrain.WaterTransparency = 0
    
    for _, v in pairs(workspace:GetDescendants()) do
        if v:IsA("BasePart") then
            v.Material = Enum.Material.Plastic
            v.Reflectance = 0
        elseif v:IsA("Decal") or v:IsA("Texture") then
            v:Destroy()
        elseif v:IsA("ParticleEmitter") or v:IsA("Trail") then
            v.Enabled = false
        end
    end
    print("Lag reduzido: Texturas removidas")
end)
