-- 6. Spin Player (Fazer o alvo girar)
local spinning = false
btn(tabs.Troll, "Spin Player", 210).MouseButton1Click:Connect(function()
    if selectedPlayer and selectedPlayer.Character then
        spinning = not spinning
        local hrp = selectedPlayer.Character:FindFirstChild("HumanoidRootPart")
        if hrp then
            local velocity = hrp:FindFirstChild("SpinVelocity") or Instance.new("BodyAngularVelocity", hrp)
            velocity.Name = "SpinVelocity"
            if spinning then
                velocity.AngularVelocity = Vector3.new(0, 50, 0)
                velocity.MaxTorque = Vector3.new(0, math.huge, 0)
            else
                velocity:Destroy()
            end
        end
    end
end)
