-- Função que contém o seu script do Escape da Lava
local function executarEscapeLava()
    -- Script: Lendas Brabas Beta + Auto-Farm
    local Player = game.Players.LocalPlayer
    local PlayerGui = Player:WaitForChild("PlayerGui")
    
    local screenGui = Instance.new("ScreenGui")
    screenGui.Name = "LendasBrabasGui"
    screenGui.ResetOnSpawn = false
    screenGui.Parent = PlayerGui

    local frame = Instance.new("Frame")
    frame.Size = UDim2.new(0, 260, 0, 480)
    frame.Position = UDim2.new(0.5, -130, 0.4, -240)
    frame.BackgroundColor3 = Color3.fromRGB(20, 20, 20)
    frame.Active = true
    frame.Draggable = true
    frame.Parent = screenGui

    local frameCorner = Instance.new("UICorner", frame)
    frameCorner.CornerRadius = UDim.new(0, 10)

    local title = Instance.new("TextLabel", frame)
    title.Size = UDim2.new(1, 0, 0, 40)
    title.BackgroundTransparency = 1
    title.RichText = true
    title.Text = '<font color="rgb(255, 255, 0)">Lendas Brabas </font><font color="rgb(255, 0, 0)">Beta</font>'
    title.TextSize = 22
    title.Font = Enum.Font.SourceSansBold

    local worlds = game:GetService("Workspace"):WaitForChild("DynamicObjects"):WaitForChild("Worlds")
    local listaTeleportes = {
        {nome = "Wins Level 1", path = worlds.Rainbow.WinPortal.Touch},
        {nome = "Wins Level 2", path = worlds.Volcano.WinPortal.Touch},
        {nome = "Wins Level 3", path = worlds.Frozen.WinPortal.Touch},
        {nome = "Wins Level 4", path = worlds.Space.WinPortal.Touch},
        {nome = "Wins Level 5", path = worlds.Beach.End.Part}
    }

    local autoFarmActive = false
    local autoBtn = Instance.new("TextButton", frame)
    autoBtn.Size = UDim2.new(0.85, 0, 0, 45)
    autoBtn.Position = UDim2.new(0.075, 0, 0, 380)
    autoBtn.Text = "Automatização: DESLIGADO"
    autoBtn.BackgroundColor3 = Color3.fromRGB(200, 0, 0)
    autoBtn.TextColor3 = Color3.new(1, 1, 1)
    autoBtn.Font = Enum.Font.SourceSansBold
    autoBtn.TextSize = 16

    Instance.new("UICorner", autoBtn).CornerRadius = UDim.new(0, 8)

    spawn(function()
        while true do
            task.wait(0.5)
            if autoFarmActive then
                for _, info in pairs(listaTeleportes) do
                    if not autoFarmActive then break end
                    if Player.Character and Player.Character:FindFirstChild("HumanoidRootPart") then
                        pcall(function() Player.Character.HumanoidRootPart.CFrame = info.path.CFrame end)
                    end
                    task.wait(1.5)
                end
            end
        end
    end)

    autoBtn.MouseButton1Click:Connect(function()
        autoFarmActive = not autoFarmActive
        autoBtn.Text = autoFarmActive and "Automatização: LIGADO" or "Automatização: DESLIGADO"
        autoBtn.BackgroundColor3 = autoFarmActive and Color3.fromRGB(0, 200, 0) or Color3.fromRGB(200, 0, 0)
    end)

    -- Criar botões manuais
    local currentY = 80
    for _, info in pairs(listaTeleportes) do
        local btnM = Instance.new("TextButton", frame)
        btnM.Size = UDim2.new(0.85, 0, 0, 45)
        btnM.Position = UDim2.new(0.075, 0, 0, currentY)
        btnM.Text = info.nome
        btnM.BackgroundColor3 = Color3.fromRGB(200, 0, 0)
        btnM.TextColor3 = Color3.new(1, 1, 1)
        btnM.Font = Enum.Font.SourceSansBold
        Instance.new("UICorner", btnM).CornerRadius = UDim.new(0, 8)
        
        btnM.MouseButton1Click:Connect(function()
            if Player.Character and Player.Character:FindFirstChild("HumanoidRootPart") then
                pcall(function() Player.Character.HumanoidRootPart.CFrame = info.path.CFrame end)
            end
        end)
        currentY = currentY + 55
    end

    local closeBtn = Instance.new("TextButton", frame)
    closeBtn.Size = UDim2.fromOffset(30, 30)
    closeBtn.Position = UDim2.new(1, -35, 0, 5)
    closeBtn.Text = "X"
    closeBtn.BackgroundColor3 = Color3.new(1,0,0)
    closeBtn.MouseButton1Click:Connect(function() screenGui:Destroy() end)
end

-- Botão na aba JOGOS do Administrador Principal
btn(tabs.Jogos, "Escape da Lava (Lendas Brabas)", 10).MouseButton1Click:Connect(function()
    executarEscapeLava()
    print("Script Lendas Brabas executado!")
end)
